def longest_palindrome(s):
    s = s.lower()
    n = len(s)
    res = ""
    for i in range(n):
        for j in range(i + 1, n + 1):
            substr = s[i:j]
            if substr == substr[::-1] and len(substr) > len(res):
                res = substr
    return res

